\label{thm:sob-smyth}
For a $T_0$-space $X$, the following conditions are equivalent:
\begin{enumerate}[\rm (1)]
\item $X$ is sober.
\item $P_{\!S}(X)$ is sober.
\end{enumerate}

\label{lem:iterate-principal}
Let $K\in\mathcal Q(X)$ and $n\geq1$. Then $P_{\!S}^{n-1}(K)$ is a compact saturated subset of $P_{\!S}^{n-1}(X)$ and
\begin{equation}\label{eq:iterate-principal}
   P_{\!S}^n(K)=\mathop{\uparrow}\!_{P_{\!S}^n(X)}P_{\!S}^{n-1}(K).
\end{equation}
In particular, $P_{\!S}^n(K)$ is a saturated subspace of $P_{\!S}^n(X)$.

\label{thm:localization}
Let $X$ be a $T_0$-space and $n\geq1$. The following are equivalent:
\begin{enumerate}[\rm (1)]
\item $P_{\!S}^n(X)$ is co-sober.
\item $P_{\!S}^n(K)$ is co-sober for every $K\in\mathcal Q(X)$.
\end{enumerate}

\label{thm:compact-Hausdorff}
Let $C$ be compact Hausdorff and $\mathcal A\in\operatorname{K\!\text{-}Irr}(P_{\!S}(C))$. Then
\begin{equation}\label{eq:union-generator}
   \mathcal A
   =\mathop{\uparrow}\!_{P_{\!S}(C)}\!\left(\bigcup\mathcal A\right).
\end{equation}
Consequently, $P_{\!S}(C)$ is co-sober.
